{
  "preset": "fastapi-vanilla",
  "architecture": "A SQLite table stores calculation history. A database module offers functions to add, list, and clear history. FastAPI routes under /api/calc call these functions. A single HTML page displays the history and has a form to perform a calculation.",
  "endpoints": [
    {
      "method": "POST",
      "path": "/api/calc",
      "summary": "Perform a calculation and save the result",
      "request_fields": [
        {"name": "a", "type": "number"},
        {"name": "b", "type": "number"},
        {"name": "operation", "type": "string", "description": "Allowed values: 'add', 'subtract', 'multiply', 'divide'"}
      ],
      "response_status": 201,
      "response_fields": [
        {"name": "id", "type": "integer"},
        {"name": "a", "type": "number"},
        {"name": "b", "type": "number"},
        {"name": "operation", "type": "string"},
        {"name": "result", "type": "number"}
      ],
      "errors": [
        {"status": 400, "detail": "Operation must be one of 'add', 'subtract', 'multiply', 'divide'"},
        {"status": 400, "detail": "Cannot divide by zero"}
      ],
      "examples": [
        {
          "description": "adds two numbers",
          "status": 201,
          "request": {"a": 5, "b": 3, "operation": "add"},
          "response": {"a": 5, "b": 3, "operation": "add", "result": 8}
        },
        {
          "description": "subtracts two numbers",
          "status": 201,
          "request": {"a": 10, "b": 4, "operation": "subtract"},
          "response": {"a": 10, "b": 4, "operation": "subtract", "result": 6}
        },
        {
          "description": "multiplies two numbers",
          "status": 201,
          "request": {"a": 7, "b": 2, "operation": "multiply"},
          "response": {"a": 7, "b": 2, "operation": "multiply", "result": 14}
        },
        {
          "description": "divides two numbers",
          "status": 201,
          "request": {"a": 8, "b": 2, "operation": "divide"},
          "response": {"a": 8, "b": 2, "operation": "divide", "result": 4}
        },
        {
          "description": "rejects invalid operation",
          "status": 400,
          "request": {"a": 5, "b": 3, "operation": "mod"},
          "response": {"detail": "Operation must be one of 'add', 'subtract', 'multiply', 'divide'"}
        },
        {
          "description": "rejects division by zero",
          "status": 400,
          "request": {"a": 5, "b": 0, "operation": "divide"},
          "response": {"detail": "Cannot divide by zero"}
        }
      ]
    },
    {
      "method": "GET",
      "path": "/api/calc",
      "summary": "List all calculation history, newest first",
      "request_fields": [],
      "response_status": 200,
      "response_fields": [
        {"name": "items", "type": "array", "description": "objects with id, a, b, operation, result"}
      ],
      "errors": [],
      "examples": [
        {
          "description": "lists calculation history",
          "status": 200,
          "request": {},
          "response": {}
        }
      ]
    },
    {
      "method": "DELETE",
      "path": "/api/calc",
      "summary": "Clear all calculation history",
      "request_fields": [],
      "response_status": 200,
      "response_fields": [
        {"name": "cleared", "type": "boolean"}
      ],
      "errors": [],
      "examples": [
        {
          "description": "clears calculation history",
          "status": 200,
          "request": {},
          "response": {"cleared": true}
        }
      ]
    }
  ],
  "tables": [
    {
      "name": "history",
      "columns": [
        {"name": "id", "type": "INTEGER", "constraints": "PRIMARY KEY AUTOINCREMENT"},
        {"name": "a", "type": "REAL", "constraints": "NOT NULL"},
        {"name": "b", "type": "REAL", "constraints": "NOT NULL"},
        {"name": "operation", "type": "TEXT", "constraints": "NOT NULL"},
        {"name": "result", "type": "REAL", "constraints": "NOT NULL"},
        {"name": "timestamp", "type": "TIMESTAMP", "constraints": "DEFAULT CURRENT_TIMESTAMP"}
      ]
    }
  ],
  "db_functions": [
    {
      "name": "add_calculation",
      "signature": "add_calculation(a: float, b: float, operation: str, result: float) -> dict",
      "description": "Insert and return the new row"
    },
    {
      "name": "list_history",
      "signature": "list_history() -> list[dict]",
      "description": "All rows, newest first"
    },
    {
      "name": "clear_history",
      "signature": "clear_history() -> None",
      "description": "Clear all rows"
    }
  ],
  "ui_features": [
    "Form with inputs for a, b, and operation, and a Calculate button",
    "List of calculation history with a timestamp for each entry",
    "Button to clear the calculation history",
    "Display error messages from the API"
  ]
}

