{"thought":"I need to implement the JavaScript logic to handle form submission, display the history, and clear the history.","action":"write_file","path":"static/app.js","content":"const form = document.getElementById("calc-form");
const history = document.getElementById("history");
const errorBox = document.getElementById("error");
const clearButton = document.getElementById("clear-history");

async function loadHistory() {
    const res = await fetch("/api/calc");
    const data = await res.json();
    history.innerHTML = "";
    for (const item of data.items) {
        const li = document.createElement("li");
        li.textContent = `${item.a} ${item.operation} ${item.b} = ${item.result} (ID: ${item.id})`;
        history.appendChild(li);
    }
}

form.addEventListener("submit", async (ev) => {
    ev.preventDefault();
    errorBox.textContent = "";
    const a = parseFloat(document.getElementById("a").value);
    const b = parseFloat(document.getElementById("b").value);
    const operation = document.getElementById("operation").value;
    const res = await fetch("/api/calc", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ a, b, operation })
    });
    const data = await res.json();
    if (!res.ok) {
        errorBox.textContent = typeof data.detail === "string" ? data.detail : "Please check your input";
        return;
    }
    await loadHistory();
});

clearButton.addEventListener("click", async () => {
    const res = await fetch("/api/calc", {
        method: "DELETE"
    });
    const data = await res.json();
    if (res.ok) {
        await loadHistory();
    } else {
        errorBox.textContent = data.detail;
    }
});

loadHistory();"}

